import React, { useEffect, useMemo, useState } from 'react'
import axios from 'axios'
import {
  Activity, ArrowDownToLine, ArrowRight, Bell, CalendarDays, Check, CheckCircle2,
  ChevronDown, ChevronRight, CircleHelp, Clock3, FilePlus2, FileText, Filter,
  HeartPulse, Home, LayoutDashboard, LogOut, Menu, MoreHorizontal, Pill,
  Plus, Search, Send, Settings, ShieldCheck, Sparkles, Stethoscope, Upload,
  UserRound, Users, X
} from 'lucide-react'
import { getToken, initAuth, removeToken, setToken } from './auth'

const API = 'http://localhost:4000'
const NAV = [
  { group: 'Workspace', items: [['dashboard', 'Dashboard', LayoutDashboard], ['patients', 'Patients', Users], ['records', 'Medical records', FileText], ['medications', 'Medications', Pill], ['doctors', 'Doctors', Stethoscope], ['visits', 'Visits', CalendarDays], ['followups', 'Follow-ups', Clock3], ['timeline', 'Timeline', Activity]] },
  { group: 'Tools', items: [['assistant', 'AI assistant', Sparkles], ['search', 'Search', Search], ['settings', 'Settings', Settings]] }
]
const TITLES = { dashboard: 'Your health, organized', patients: 'Patients', patient: 'Patient profile', records: 'Medical records', medications: 'Medications', doctors: 'Doctors', visits: 'Visits', followups: 'Follow-ups', timeline: 'Health timeline', assistant: 'MedRef AI assistant', search: 'Search your records', settings: 'Settings' }
const DEMO_PATIENTS = [{ id: 'demo-1', name: 'Alex Morgan', dob: '1992-03-14', relationship: 'Self' }, { id: 'demo-2', name: 'Jamie Morgan', dob: '1994-06-21', relationship: 'Partner' }]
const DEMO = {
  records: [
    { id: 'dr1', filename: 'Annual blood panel.pdf', type: 'Lab report', patientName: 'Alex Morgan', doctor: 'Dr. Maya Chen', created_at: '2026-09-20' },
    { id: 'dr2', filename: 'Cardiology visit summary.pdf', type: 'Visit summary', patientName: 'Alex Morgan', doctor: 'Dr. Rafael Ortiz', created_at: '2026-09-15' },
    { id: 'dr3', filename: 'Chest X-ray.png', type: 'Imaging', patientName: 'Jamie Morgan', doctor: 'Dr. Maya Chen', created_at: '2026-09-08' }
  ],
  medications: [
    { id: 'dm1', name: 'Vitamin D3', dosage: '1,000 IU', frequency: 'Once daily', start_date: '2026-08-01', status: 'Active', patientName: 'Alex Morgan' },
    { id: 'dm2', name: 'Cetirizine', dosage: '10 mg', frequency: 'As needed', start_date: '2026-07-12', status: 'Active', patientName: 'Alex Morgan' }
  ],
  doctors: [{ id: 'dd1', name: 'Dr. Maya Chen', specialty: 'Primary care', clinic: 'Northside Family Clinic', visits: 4 }, { id: 'dd2', name: 'Dr. Rafael Ortiz', specialty: 'Cardiology', clinic: 'Harbor Medical Center', visits: 2 }],
  visits: [{ id: 'dv1', date: '2026-09-15', provider: 'Dr. Rafael Ortiz', reason: 'Annual heart health review', patientName: 'Alex Morgan' }, { id: 'dv2', date: '2026-08-22', provider: 'Dr. Maya Chen', reason: 'Routine check-up', patientName: 'Alex Morgan' }],
  followups: [{ id: 'df1', date: '2026-10-06', doctor: 'Dr. Maya Chen', reason: 'Review lab results', status: 'Upcoming', patientName: 'Alex Morgan' }, { id: 'df2', date: '2026-10-18', doctor: 'Dr. Rafael Ortiz', reason: 'Follow-up consultation', status: 'Upcoming', patientName: 'Alex Morgan' }]
}

function readUser() {
  try {
    const raw = localStorage.getItem('medref_user')
    return raw ? JSON.parse(raw) : null
  } catch {
    return null
  }
}

function safeSetStorage(key, value) {
  try {
    localStorage.setItem(key, value)
  } catch {
    // Ignore restricted or unavailable storage environments.
  }
}

function safeRemoveStorage(key) {
  try {
    localStorage.removeItem(key)
  } catch {
    // Ignore restricted or unavailable storage environments.
  }
}
function dateText(value, options = { month: 'short', day: 'numeric', year: 'numeric' }) { if (!value) return 'Not recorded'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString('en-US', options) }
function getAge(dob) { if (!dob) return ''; const birth = new Date(dob); const now = new Date(); return now.getFullYear() - birth.getFullYear() - (now < new Date(now.getFullYear(), birth.getMonth(), birth.getDate()) ? 1 : 0) }
function initials(name = '') { return name.split(/[\s@._-]+/).filter(Boolean).slice(0, 2).map(part => part[0]).join('').toUpperCase() || 'M' }

export default function Workspace() {
  const [view, setView] = useState(() => getToken() ? 'dashboard' : 'login')
  const [authMode, setAuthMode] = useState('login')
  const [user, setUser] = useState(readUser)
  const [demo, setDemo] = useState(false)
  const [patients, setPatients] = useState([])
  const [patientId, setPatientId] = useState('')
  const [data, setData] = useState({ records: [], medications: [], doctors: [], visits: [], followups: [] })
  const [modal, setModal] = useState('')
  const [mobileNav, setMobileNav] = useState(false)
  const [notice, setNotice] = useState('')
  const [query, setQuery] = useState('')
  const [authError, setAuthError] = useState('')
  const patient = patients.find(item => item.id === patientId) || patients[0]

  useEffect(() => { initAuth(); if (getToken()) setView('dashboard') }, [])
  useEffect(() => {
    if (!getToken() || !user?.id) return undefined
    let active = true
    Promise.allSettled([
      axios.get(`${API}/profiles`, { params: { user_id: user.id } }),
      axios.get(`${API}/documents`)
    ]).then(([profiles, records]) => {
      if (!active) return
      if (profiles.status === 'fulfilled') {
        const list = profiles.value.data.map(item => ({ ...item, relationship: item.relationship || 'Family' }))
        setPatients(list)
        if (list[0]) setPatientId(list[0].id)
      }
      if (records.status === 'fulfilled') setData(current => ({ ...current, records: records.value.data }))
    })
    return () => { active = false }
  }, [user])
  useEffect(() => {
    if (!getToken() || demo || !patientId) return undefined
    let active = true
    Promise.allSettled([
      axios.get(`${API}/medicines`, { params: { profile_id: patientId } }),
      axios.get(`${API}/visits`, { params: { profile_id: patientId } })
    ]).then(([medications, visits]) => {
      if (!active) return
      setData(current => ({
        ...current,
        ...(medications.status === 'fulfilled' ? { medications: medications.value.data.map(item => ({ ...item, patientName: patient?.name })) } : {}),
        ...(visits.status === 'fulfilled' ? { visits: visits.value.data.map(item => ({ ...item, patientName: patient?.name })) } : {})
      }))
    })
    return () => { active = false }
  }, [patientId, demo, patient?.name])
  useEffect(() => { if (!notice) return undefined; const timer = setTimeout(() => setNotice(''), 3500); return () => clearTimeout(timer) }, [notice])

  async function submitAuth(event) {
    event.preventDefault(); setAuthError('')
    const form = new FormData(event.currentTarget)
    const email = form.get('email'); const password = form.get('password')
    try {
      if (authMode === 'register') {
        await axios.post(`${API}/auth/register`, { name: form.get('name'), email, password })
        setNotice('Account created. You can sign in now.'); setAuthMode('login')
      } else {
        const response = await axios.post(`${API}/auth/login`, { email, password })
        setToken(response.data.token); safeSetStorage('medref_user', JSON.stringify(response.data.user))
        setUser(response.data.user); setView('dashboard')
      }
    } catch (error) { setAuthError(error.response?.data?.error || 'Could not reach MedRef. Check that the backend is running and try again.') }
  }
  function enterDemo() { setDemo(true); setUser({ name: 'Alex Morgan', email: 'demo@medref.example' }); setPatients(DEMO_PATIENTS); setPatientId(DEMO_PATIENTS[0].id); setData(DEMO); setView('dashboard') }
  function signOut() { if (!demo) { removeToken(); safeRemoveStorage('medref_user') } setDemo(false); setUser(null); setView('login'); setNotice('You have been signed out.') }
  async function save(kind, values) {
    const profile = patient?.id
    if (kind === 'patient') {
      let entry
      if (demo) entry = { ...values, id: `demo-${Date.now()}`, relationship: values.relationship || 'Family' }
      else { const response = await axios.post(`${API}/profiles`, { user_id: user.id, name: values.name, dob: values.dob }); entry = { ...response.data, relationship: values.relationship || 'Family' } }
      setPatients(list => [...list, entry]); setPatientId(entry.id); setNotice('Patient profile added.'); return
    }
    if (kind === 'medication') {
      const entry = { ...values, id: `med-${Date.now()}`, patientName: patient?.name, status: 'Active' }
      if (!demo) { if (!profile) throw new Error('Add a patient profile first.'); const response = await axios.post(`${API}/medicines`, { profile_id: profile, name: values.name, dosage: values.dosage, start_date: values.start_date, end_date: values.end_date, notes: values.frequency }); entry.id = response.data.id }
      setData(current => ({ ...current, medications: [entry, ...current.medications] }))
    } else if (kind === 'visit') {
      const entry = { ...values, id: `visit-${Date.now()}`, provider: values.provider, patientName: patient?.name }
      if (!demo) { if (!profile) throw new Error('Add a patient profile first.'); const response = await axios.post(`${API}/visits`, { profile_id: profile, date: values.date, provider: values.provider, reason: values.reason, notes: values.notes }); entry.id = response.data.id }
      setData(current => ({ ...current, visits: [entry, ...current.visits] }))
    } else if (kind === 'doctor') setData(current => ({ ...current, doctors: [{ ...values, id: `doctor-${Date.now()}`, visits: 0 }, ...current.doctors] }))
    else if (kind === 'followup') setData(current => ({ ...current, followups: [{ ...values, id: `followup-${Date.now()}`, status: 'Upcoming', patientName: patient?.name }, ...current.followups] }))
    setNotice(demo ? 'Added to this demo session only.' : ['doctor', 'followup'].includes(kind) ? 'This item is only held for this session; the backend does not yet sync doctors or follow-ups.' : 'Saved to your records.')
  }
  async function upload(file, values, onProgress) {
    if (!file) throw new Error('Choose a file to upload.')
    if (!['application/pdf', 'image/jpeg', 'image/png'].includes(file.type)) throw new Error('Choose a PDF, JPG, JPEG, or PNG file.')
    if (file.size > 20 * 1024 * 1024) throw new Error('The file must be smaller than 20 MB.')
    if (demo) {
      setData(current => ({ ...current, records: [{ id: `record-${Date.now()}`, filename: file.name, type: values.type, created_at: values.date, patientName: patient?.name, doctor: values.doctor }, ...current.records] }))
      setNotice('Sample record added to this demo session only.'); return
    }
    if (!patient) throw new Error('Add a patient profile before uploading a record.')
    const body = new FormData(); body.append('file', file); body.append('profile_id', patient.id)
    const response = await axios.post(`${API}/documents`, body, { headers: { 'Content-Type': 'multipart/form-data' }, onUploadProgress: event => onProgress(event.total ? Math.round(event.loaded * 100 / event.total) : 0) })
    setData(current => ({ ...current, records: [{ id: response.data.id, filename: file.name, type: values.type, created_at: values.date, patientName: patient.name, doctor: values.doctor }, ...current.records] }))
    setNotice('Record file uploaded. This backend does not store the type, date, doctor, or notes fields yet.')
  }

  if (!getToken() && !demo) return <AuthPage mode={authMode} setMode={setAuthMode} onSubmit={submitAuth} onDemo={enterDemo} error={authError} notice={notice} />

  const action = { dashboard: ['Upload record', 'upload', Upload], records: ['Upload record', 'upload', Upload], patients: ['Add patient', 'patient', Plus], medications: ['Add medication', 'medication', Plus], doctors: ['Add doctor', 'doctor', Plus], visits: ['Record visit', 'visit', Plus], followups: ['Add follow-up', 'followup', Plus] }[view]
  const ActionIcon = action?.[2]
  return <div className="medref-shell">
    <aside className={`side-rail ${mobileNav ? 'side-rail-open' : ''}`}>
      <a href="#dashboard" className="wordmark" onClick={event => { event.preventDefault(); setView('dashboard'); setMobileNav(false) }}><span className="wordmark-icon"><HeartPulse size={20} /></span><span>medref<span className="wordmark-dot">.</span></span></a>
      <div className="space-switcher"><span className="space-avatar"><HeartPulse size={15} /></span><span><small>PERSONAL SPACE</small><strong>My care workspace</strong></span><ChevronDown size={15} /></div>
      <nav className="rail-nav" aria-label="Main navigation">{NAV.map(group => <div className="rail-group" key={group.group}><span className="rail-label">{group.group}</span>{group.items.map(([id, label, Icon]) => <button key={id} className={`rail-link ${view === id || (view === 'patient' && id === 'patients') ? 'rail-link-active' : ''}`} onClick={() => { setView(id); setMobileNav(false) }} aria-current={view === id ? 'page' : undefined}><Icon size={18} /><span>{label}</span>{id === 'records' && data.records.length > 0 && <small>{data.records.length}</small>}</button>)}</div>)}</nav>
      <div className="rail-support"><span><CircleHelp size={18} /></span><div><strong>Need a hand?</strong><small>Visit the help center</small></div><ChevronRight size={15} /></div>
      <div className="rail-profile"><Avatar name={user?.name || user?.email} /><span><strong>{user?.name || 'Your account'}</strong><small>{user?.email || 'Personal workspace'}</small></span><button className="plain-icon" onClick={signOut} aria-label="Sign out"><LogOut size={17} /></button></div>
    </aside>
    {mobileNav && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => setMobileNav(false)} />}
    <div className="main-column">
      <header className="app-topbar"><button className="plain-icon mobile-menu" aria-label="Open navigation" onClick={() => setMobileNav(true)}><Menu size={21} /></button><div className="current-patient"><span>Viewing records for</span><label><UserRound size={16} /><select aria-label="Current patient" value={patient?.id || ''} disabled={!patients.length} onChange={event => setPatientId(event.target.value)}>{!patients.length && <option value="">No patient selected</option>}{patients.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select><ChevronDown size={14} /></label></div><div className="topbar-right">{demo && <span className="demo-badge"><i /> Demo data</span>}<button className="top-search" onClick={() => setView('search')}><Search size={17} /><span>Search records</span><kbd>Ctrl K</kbd></button><button className="plain-icon bell-button" aria-label="Open follow-ups" onClick={() => setView('followups')}><Bell size={19} /><i /></button><button className="top-user" onClick={signOut} aria-label="Sign out"><Avatar name={user?.name || user?.email} size="compact"/><ChevronDown size={14}/></button></div></header>
      <main className="page-content">
        {demo && <div className="demo-banner"><Sparkles size={15} /><span>You're viewing synthetic demo data. Changes are not saved.</span><button onClick={() => setView('settings')}>About demo data</button></div>}
        <div className="page-title-row"><div>{view === 'dashboard' && <span className="greeting-label">{new Date().getHours() < 12 ? 'A FRESH LOOK AT YOUR CARE' : 'YOUR HEALTH WORKSPACE'}</span>}<h1>{view === 'dashboard' ? `Good ${new Date().getHours() < 12 ? 'morning' : 'day'}, ${user?.name?.split(' ')[0] || 'there'}` : TITLES[view]}</h1><p>{view === 'dashboard' ? 'Here is an overview of your medical records.' : pageDescription(view)}</p></div>{action && <button className="primary-button" onClick={() => setModal(action[1])}><ActionIcon size={17}/>{action[0]}</button>}</div>
        {view === 'dashboard' && <Dashboard data={data} patient={patient} navigate={setView} openModal={setModal} ask={() => setView('assistant')} demo={demo} />}
        {view === 'patients' && <PatientList patients={patients} add={() => setModal('patient')} open={item => { setPatientId(item.id); setView('patient') }} />}
        {view === 'patient' && <PatientOverview patient={patient} data={data} navigate={setView} />}
        {view === 'records' && <Records data={data} demo={demo} upload={() => setModal('upload')} />}
        {view === 'medications' && <Medications data={data} add={() => setModal('medication')} />}
        {view === 'doctors' && <Doctors data={data} add={() => setModal('doctor')} />}
        {view === 'visits' && <Visits data={data} add={() => setModal('visit')} />}
        {view === 'followups' && <Followups data={data} add={() => setModal('followup')} />}
        {view === 'timeline' && <Timeline data={data} />}
        {view === 'assistant' && <Assistant patient={patient} demo={demo} />}
        {view === 'search' && <GlobalSearch data={data} query={query} setQuery={setQuery} />}
        {view === 'settings' && <SettingsPage user={user} demo={demo} />}
      </main>
    </div>
    {modal && <Modal type={modal} patient={patient} onClose={() => setModal('')} onSave={save} onUpload={upload} />}
    {notice && <div className="toast" role="status"><CheckCircle2 size={18}/><span>{notice}</span><button className="plain-icon" onClick={() => setNotice('')} aria-label="Dismiss notification"><X size={16}/></button></div>}
  </div>
}

function pageDescription(view) {
  return ({ patients: 'Manage the people whose records you care for.', patient: 'A clear overview of one person\'s care.', records: 'Store, organize, and quickly access important documents.', medications: 'Keep an up-to-date list of recorded medications.', doctors: 'Keep care teams and contact details close at hand.', visits: 'Review appointments and notes in one place.', followups: 'Keep upcoming care steps from slipping through the cracks.', timeline: 'Important moments in care, in chronological order.', assistant: 'Find information in the medical records stored in MedRef.', search: 'Find a document, medication, visit, or care team member.', settings: 'Manage your account and workspace preferences.' })[view] || ''
}

function Avatar({ name, size = 'normal' }) { return <span className={`user-avatar avatar-${size}`} aria-hidden="true">{initials(name)}</span> }
function StatCard({ icon: Icon, label, value, note, tone, onClick }) { return <button className="stat-card" onClick={onClick}><span className={`stat-icon ${tone}`}><Icon size={19}/></span><span className="stat-label">{label}</span><strong>{value}</strong><small>{note}</small><ArrowRight className="stat-arrow" size={15}/></button> }
function PanelTitle({ title, action, onAction }) { return <div className="panel-title"><h2>{title}</h2>{action && <button className="link-button" onClick={onAction}>{action}<ChevronRight size={15}/></button>}</div> }
function Empty({ icon: Icon, title, text, action, onAction }) { return <div className="empty-box"><span><Icon size={22}/></span><h3>{title}</h3><p>{text}</p>{action && <button className="secondary-button" onClick={onAction}><Plus size={15}/>{action}</button>}</div> }

function Dashboard({ data, patient, navigate, openModal, ask, demo }) {
  const cards = [['records', 'Medical records', data.records.length, 'Documents in your library', FileText, 'blue'], ['medications', 'Active medications', data.medications.filter(item => !item.status || item.status === 'Active').length, 'Recorded for this patient', Pill, 'green'], ['followups', 'Upcoming follow-ups', data.followups.filter(item => !item.status || item.status === 'Upcoming').length, 'Next care steps', CalendarDays, 'amber'], ['visits', 'Recent visits', data.visits.length, 'Appointments on record', Stethoscope, 'lavender']]
  return <>
    <section className="stats-grid">{cards.map(([id, label, value, note, icon, tone]) => <StatCard key={id} label={label} value={value} note={note} icon={icon} tone={tone} onClick={() => navigate(id)} />)}</section>
    <div className="dashboard-columns"><section className="surface records-surface"><PanelTitle title="Recent medical records" action="View all records" onAction={() => navigate('records')}/>{data.records.length ? <div className="record-list">{data.records.slice(0, 4).map(record => <RecordRow key={record.id} record={record}/>)}</div> : <Empty icon={FileText} title="No records yet" text="Upload a report or visit summary to start building your health history." action="Upload record" onAction={() => openModal('upload')}/>}</section>
      <section className="surface followups-surface"><PanelTitle title="Upcoming follow-ups" action="See schedule" onAction={() => navigate('followups')}/>{data.followups.length ? <div className="upcoming-list">{data.followups.slice(0, 3).map(item => <FollowupRow key={item.id} item={item}/>)}</div> : <Empty icon={CalendarDays} title="Nothing scheduled" text="Keep a note of your next check-in or appointment." action="Add follow-up" onAction={() => openModal('followup')}/>}</section>
      <section className="surface activity-surface"><PanelTitle title="Recent activity" action="Open timeline" onAction={() => navigate('timeline')}/><ActivityList data={data}/></section>
      <section className="assistant-callout"><div className="callout-top"><span className="callout-icon"><Sparkles size={18}/></span><span>MEDREF ASSISTANT</span><span className="record-grounded"><ShieldCheck size={14}/>Record-based</span></div><h2>Make sense of your records.</h2><p>Ask a question and find relevant information in the records you have stored.</p><button className="callout-input" onClick={ask}><span>Ask about a report, medication, visit, or follow-up...</span><i><ArrowRight size={16}/></i></button><small>Information only. Not a substitute for professional medical advice.</small></section>
    </div>{demo && <p className="synthetic-note"><Sparkles size={14}/>All sample records and patient names are synthetic demo content.</p>}{!patient && !demo && <div className="inline-note"><CircleHelp size={17}/><span>Add a patient profile to connect records, medications, and visits.</span><button onClick={() => openModal('patient')}>Add patient</button></div>}
  </>
}
function RecordRow({ record }) { return <div className="record-row"><span className="document-symbol"><FileText size={18}/></span><span className="record-name"><strong>{record.filename || 'Medical record'}</strong><small>{record.type || 'Medical record'} <i/> {record.patientName || 'Current patient'}</small></span><time>{dateText(record.created_at)}</time><button className="plain-icon" aria-label={`More actions for ${record.filename || 'record'}`}><MoreHorizontal size={18}/></button></div> }
function FollowupRow({ item }) { return <div className="followup-row"><span className="date-chip"><strong>{new Date(item.date).getDate()}</strong><small>{new Date(item.date).toLocaleDateString('en-US', { month: 'short' })}</small></span><span className="followup-copy"><strong>{item.reason || 'Follow-up visit'}</strong><small>{item.doctor || item.provider || 'Care team'} <i/> {item.patientName || 'Patient'}</small></span><span className="upcoming-tag">Upcoming</span></div> }
function ActivityList({ data }) { const entries = [...data.records.map(item => ({ id: `r${item.id}`, title: 'Medical record added', detail: item.filename, date: item.created_at, icon: FileText })), ...data.medications.map(item => ({ id: `m${item.id}`, title: 'Medication recorded', detail: item.name, date: item.start_date, icon: Pill })), ...data.visits.map(item => ({ id: `v${item.id}`, title: 'Visit recorded', detail: item.provider, date: item.date, icon: Stethoscope }))].sort((a,b) => new Date(b.date) - new Date(a.date)).slice(0,4); return entries.length ? <div className="activity-list">{entries.map(item => <div className="activity-entry" key={item.id}><span><item.icon size={15}/></span><div><strong>{item.title}</strong><small>{item.detail || 'Health record'}</small></div><time>{dateText(item.date, { month: 'short', day: 'numeric' })}</time></div>)}</div> : <div className="quiet-empty"><Activity size={19}/><p>Your activity will appear here as you add records.</p></div> }

function PatientList({ patients, add, open }) { return <section className="page-section"><div className="section-lead"><div><h2>Your people</h2><p>Each patient has a separate, organized health history.</p></div></div>{patients.length ? <div className="people-grid">{patients.map(item => <button className="person-card" key={item.id} onClick={() => open(item)}><Avatar name={item.name}/><span><strong>{item.name}</strong><small>{item.relationship || 'Family member'}{getAge(item.dob) ? ` · ${getAge(item.dob)} years` : ''}</small></span><ChevronRight size={18}/></button>)}</div> : <Empty icon={Users} title="No patient profiles yet" text="Create a profile to organize records for yourself or a family member." action="Add patient" onAction={add}/>}</section> }
function PatientOverview({ patient, data, navigate }) { if (!patient) return <Empty icon={Users} title="Choose a patient" text="Select a patient from the header to see their health profile."/>; return <section className="page-section"><div className="patient-hero"><Avatar name={patient.name}/><div><small>PATIENT PROFILE</small><h2>{patient.name}</h2><p>{getAge(patient.dob) ? `${getAge(patient.dob)} years` : 'Age not added'} <i/> {patient.relationship || 'Family'}</p></div><button className="secondary-button" onClick={() => {}}>Edit profile</button></div><div className="tabs" role="tablist" aria-label="Patient profile sections">{[['Overview','patient'],['Records','records'],['Medications','medications'],['Doctors','doctors'],['Visits','visits'],['Timeline','timeline']].map(([name,id]) => <button role="tab" aria-selected={id === 'patient'} className={id === 'patient' ? 'active' : ''} key={id} onClick={() => id !== 'patient' && navigate(id)}>{name}</button>)}</div><div className="profile-stats">{[['Records',data.records.length,FileText],['Medications',data.medications.length,Pill],['Doctors',data.doctors.length,Stethoscope],['Visits',data.visits.length,CalendarDays],['Follow-ups',data.followups.length,Clock3]].map(([label,value,Icon]) => <div className="profile-stat" key={label}><Icon size={17}/><strong>{value}</strong><small>{label}</small></div>)}</div><section className="surface details-surface"><PanelTitle title="Patient details"/><Detail label="Relationship" value={patient.relationship || 'Not specified'}/><Detail label="Date of birth" value={dateText(patient.dob)}/><Detail label="Gender" value="Not provided"/></section></section> }
function Detail({label,value}) { return <div className="detail-row"><span>{label}</span><strong>{value}</strong></div> }

function Records({ data, demo, upload }) { const [term,setTerm]=useState(''); const [kind,setKind]=useState('All types'); const kinds=['All types',...new Set(data.records.map(item=>item.type).filter(Boolean))]; const list=data.records.filter(item=>`${item.filename} ${item.type} ${item.patientName} ${item.doctor}`.toLowerCase().includes(term.toLowerCase())&&(kind==='All types'||kind===item.type)); return <section className="page-section"><div className="records-toolbar"><label className="search-field"><Search size={17}/><input aria-label="Search records" placeholder="Search records..." value={term} onChange={e=>setTerm(e.target.value)}/></label><label className="select-field"><Filter size={15}/><select aria-label="Filter by document type" value={kind} onChange={e=>setKind(e.target.value)}>{kinds.map(item=><option key={item}>{item}</option>)}</select></label><span className="row-count">{list.length} records</span></div>{list.length ? <div className="table-shell"><div className="table-header"><span>Document</span><span>Patient</span><span>Doctor</span><span>Date added</span><span/></div>{list.map(item=><div className="table-row" key={item.id}><span className="table-doc"><span className="document-symbol"><FileText size={17}/></span><span><strong>{item.filename}</strong><small>{item.type||'Medical record'}</small></span></span><span>{item.patientName||'Current patient'}</span><span>{item.doctor||'Not specified'}</span><span>{dateText(item.created_at)}</span><span className="table-buttons"><button className="plain-icon" aria-label={`Download ${item.filename}`} onClick={()=>!demo&&window.open(`${API}/documents/${item.id}/download`,'_blank','noopener')}><ArrowDownToLine size={17}/></button><button className="plain-icon" aria-label="More options"><MoreHorizontal size={18}/></button></span></div>)}</div> : <Empty icon={FileText} title={term||kind!=='All types'?'No matching records':'No medical records yet'} text={term||kind!=='All types'?'Try another search or clear the filters.':'Upload your first medical document to start organizing your records.'} action={!term&&kind==='All types'?'Upload record':undefined} onAction={upload}/>}<p className="privacy-note"><ShieldCheck size={15}/>Your documents are organized by patient and private to your account.</p></section> }
function Medications({data,add}) { return <section className="page-section"><div className="section-lead"><div><h2>Medication list</h2><p>A personal record of medications shared with your care team.</p></div><span className="care-note">MedRef does not prescribe medication.</span></div>{data.medications.length?<div className="medication-grid">{data.medications.map(item=><article className="medication-card" key={item.id}><div className="medication-head"><span className="medication-icon"><Pill size={19}/></span><span className="status-active">{item.status||'Active'}</span></div><h3>{item.name}</h3><p>{item.dosage||'Dosage not recorded'} {item.frequency?`· ${item.frequency}`:''}</p><div className="medication-dates"><Detail label="Started" value={dateText(item.start_date)}/><Detail label="Ends" value={dateText(item.end_date)}/></div><small className="medication-disclaimer">Recorded for reference. Follow your clinician's guidance.</small></article>)}</div>:<Empty icon={Pill} title="No medications recorded" text="Keep a reference list of medications mentioned in your records." action="Add medication" onAction={add}/>}</section> }
function Doctors({data,add}) { return <section className="page-section"><div className="section-lead"><div><h2>Your care team</h2><p>Clinicians and clinics connected to your health history.</p></div></div>{data.doctors.length?<div className="people-grid doctor-grid">{data.doctors.map(item=><article className="doctor-card" key={item.id}><Avatar name={item.name}/><small>{item.visits||0} visits recorded</small><h3>{item.name}</h3><p>{item.specialty||'Specialty not added'}</p><div><Stethoscope size={15}/>{item.clinic||'Clinic not added'}</div><button className="secondary-button">View profile<ArrowRight size={15}/></button></article>)}</div>:<Empty icon={Stethoscope} title="No doctors added" text="Add a clinician to keep care team details together." action="Add doctor" onAction={add}/>}</section> }
function Visits({data,add}) { return <section className="page-section"><div className="section-lead"><div><h2>Visit history</h2><p>Appointments, reasons for visit, and notes from your care team.</p></div></div>{data.visits.length?<div className="visit-list">{data.visits.map(item=><article className="visit-row" key={item.id}><span className="visit-date"><CalendarDays size={17}/>{dateText(item.date)}</span><div><h3>{item.provider||'Doctor visit'}</h3><p>{item.reason||'Visit details not added'}</p>{item.notes&&<small>{item.notes}</small>}</div><span className="visit-complete">Recorded</span></article>)}</div>:<Empty icon={CalendarDays} title="No visits recorded" text="Add a visit to keep an organized history of appointments." action="Record visit" onAction={add}/>}</section> }
function Followups({data,add}) { const [filter,setFilter]=useState('All');const list=data.followups.filter(item=>filter==='All'||item.status===filter);return <section className="page-section"><div className="records-toolbar"><div className="segmented">{['All','Upcoming','Completed','Missed'].map(item=><button className={filter===item?'active':''} key={item} onClick={()=>setFilter(item)}>{item}</button>)}</div><span className="row-count">{list.length} follow-ups</span></div>{list.length?<div className="followup-calendar">{list.map(item=><article className="calendar-row" key={item.id}><div className="calendar-date"><small>{new Date(item.date).toLocaleDateString('en-US',{month:'short'})}</small><strong>{new Date(item.date).getDate()}</strong><span>{new Date(item.date).toLocaleDateString('en-US',{weekday:'short'})}</span></div><div><small className="eyebrow">{item.status||'Upcoming'} FOLLOW-UP</small><h3>{item.reason||'Care follow-up'}</h3><p><Stethoscope size={14}/>{item.doctor||'Care team'} <i/> {item.patientName||'Patient'}</p></div><span className="status-active">{item.status||'Upcoming'}</span></article>)}</div>:<Empty icon={CalendarDays} title="No follow-ups scheduled" text="Add a reminder for the next step in care." action="Add follow-up" onAction={add}/>}</section> }

function Timeline({data}) { const [filter,setFilter]=useState('All activity');const items=useMemo(()=>[...data.records.map(x=>({id:`r${x.id}`,category:'Documents',title:x.filename,sub:`${x.type||'Medical record'} · ${x.patientName||'Patient'}`,date:x.created_at,icon:FileText})),...data.visits.map(x=>({id:`v${x.id}`,category:'Visits',title:x.reason||'Doctor visit',sub:`${x.provider||'Care team'} · ${x.patientName||'Patient'}`,date:x.date,icon:Stethoscope})),...data.medications.map(x=>({id:`m${x.id}`,category:'Medications',title:x.name,sub:`${x.dosage||'Medication'} · ${x.patientName||'Patient'}`,date:x.start_date,icon:Pill})),...data.followups.map(x=>({id:`f${x.id}`,category:'Follow-ups',title:x.reason||'Follow-up scheduled',sub:`${x.doctor||'Care team'} · ${x.status||'Upcoming'}`,date:x.date,icon:CalendarDays}))].filter(x=>filter==='All activity'||x.category===filter).sort((a,b)=>new Date(b.date)-new Date(a.date)),[data,filter]);return <section className="page-section"><div className="records-toolbar"><label className="select-field"><Filter size={15}/><select aria-label="Filter timeline" value={filter} onChange={e=>setFilter(e.target.value)}>{['All activity','Documents','Visits','Medications','Follow-ups'].map(item=><option key={item}>{item}</option>)}</select></label><span className="row-count">{items.length} events</span></div>{items.length?<div className="timeline"><div className="timeline-year">{new Date(items[0].date).getFullYear()}</div>{items.map(item=><article className="timeline-item" key={item.id}><span className="timeline-icon"><item.icon size={16}/></span><time>{dateText(item.date)}</time><div><strong>{item.title}</strong><small>{item.sub}</small></div></article>)}</div>:<Empty icon={Activity} title="Your timeline starts here" text="Records, visits, medications, and follow-ups will appear here by date."/>}</section> }

function Assistant({patient,demo}) { const [query,setQuery]=useState('');const [messages,setMessages]=useState([]);const [busy,setBusy]=useState(false);const prompts=['What reports were uploaded recently?','Summarize this patient\'s recent records.','Show medications recorded for this patient.','When was the last doctor visit?'];async function ask(text=query){if(!text.trim()||busy)return;setMessages(list=>[...list,{role:'user',text}]);setQuery('');setBusy(true);if(demo){setTimeout(()=>{setMessages(list=>[...list,{role:'assistant',text:'In an account, MedRef searches stored records and links relevant sources. This synthetic preview does not provide diagnoses or treatment recommendations.'}]);setBusy(false)},400);return}try{const response=await axios.post(`${API}/assistant/query`,{profile_id:patient?.id,query:text});setMessages(list=>[...list,{role:'assistant',text:response.data.summary,sources:response.data.sources||[]}])}catch{setMessages(list=>[...list,{role:'assistant',text:'I could not reach the records service. Try again when the backend is available.'}])}finally{setBusy(false)}}return <section className="assistant-layout"><div className="assistant-chat"><div className="assistant-intro"><span><Sparkles size={22}/></span><h2>Find answers in your records.</h2><p>Ask about information you have stored. MedRef can help you find relevant details.</p></div>{!messages.length?<div className="prompt-list">{prompts.map(text=><button key={text} onClick={()=>ask(text)}>{text}<ArrowRight size={16}/></button>)}</div>:<div className="chat-history" aria-live="polite">{messages.map((item,index)=><div className={`chat-line ${item.role}`} key={index}>{item.role==='assistant'&&<span className="chat-mark"><Sparkles size={15}/></span>}<div><p>{item.text}</p>{item.sources?.map(source=><small className="source-chip" key={source.id}><FileText size={13}/>{source.filename}</small>)}</div></div>)}{busy&&<p className="searching-note"><span/>Searching stored records</p>}</div>}<form className="chat-composer" onSubmit={event=>{event.preventDefault();ask()}}><label className="sr-only" htmlFor="assistant-input">Ask about your records</label><textarea id="assistant-input" rows="2" placeholder="Ask about a report, medication, visit, or follow-up..." value={query} onChange={event=>setQuery(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();ask()}}}/><button aria-label="Send question" disabled={!query.trim()||busy}><Send size={17}/></button><small>Enter to send · Shift + Enter for a new line</small></form></div><aside className="assistant-aside"><div className="assistant-context"><ShieldCheck size={20}/><h3>Grounded in your records</h3><p>Responses are based on information available in stored records.</p><span><UserRound size={15}/>Current patient<strong>{patient?.name||'Not selected'}</strong></span></div><div className="medical-disclaimer"><CircleHelp size={18}/><strong>Important information</strong><p>MedRef provides information from stored records and is not a doctor. It does not diagnose conditions, prescribe medications, or replace professional medical advice.</p></div></aside></section> }

function GlobalSearch({data,query,setQuery}) { const groups=[['Medical records',data.records,x=>`${x.filename} ${x.type} ${x.doctor}`,x=>x.filename,FileText],['Medications',data.medications,x=>`${x.name} ${x.dosage}`,x=>x.name,Pill],['Doctors',data.doctors,x=>`${x.name} ${x.specialty} ${x.clinic}`,x=>x.name,Stethoscope],['Visits',data.visits,x=>`${x.provider} ${x.reason}`,x=>x.reason||x.provider,CalendarDays],['Follow-ups',data.followups,x=>`${x.doctor} ${x.reason}`,x=>x.reason||'Follow-up',Clock3]];const hits=groups.map(([name,items,match,title,Icon])=>({name,Icon,items:query?items.filter(x=>match(x).toLowerCase().includes(query.toLowerCase())):[]})).filter(group=>group.items.length);return <section className="search-page"><label className="global-search"><Search size={20}/><input autoFocus aria-label="Search all records" placeholder="Search medical records, medications, doctors, visits..." value={query} onChange={e=>setQuery(e.target.value)}/><kbd>ESC</kbd></label>{!query?<p className="search-tip"><Sparkles size={16}/>Search by record name, medication, clinician, or visit detail.</p>:hits.length?<div className="search-groups">{hits.map(group=><section key={group.name}><h2>{group.name}<span>{group.items.length}</span></h2>{group.items.map(item=><div className="search-hit" key={item.id}><span className="document-symbol"><group.Icon size={16}/></span><span><strong>{item.filename||item.name||item.reason||item.provider}</strong><small>{item.type||item.specialty||item.dosage||item.patientName||dateText(item.date)}</small></span><ArrowRight size={16}/></div>)}</section>)}</div>:<Empty icon={Search} title="No results found" text="Try a different search term."/>}</section> }

function SettingsPage({user,demo}) { const [toggles,setToggles]=useState({reminders:true,updates:false,compact:false});return <section className="settings-layout"><nav><a href="#profile">Profile</a><a href="#security">Security</a><a href="#notifications">Notifications</a><a href="#appearance">Appearance</a><a href="#privacy">Data &amp; privacy</a></nav><div className="settings-content"><Setting title="Profile" description="Your account details and personal information." id="profile"><div className="settings-profile"><Avatar name={user?.name||user?.email}/><span><strong>{user?.name||'Your profile'}</strong><small>{user?.email||'Demo preview'}</small></span><button className="secondary-button" disabled={demo}>Edit profile</button></div></Setting><Setting title="Security" description="Keep your account protected." id="security"><div className="setting-line"><span><strong>Password</strong><small>Use a unique password for your account.</small></span><button className="link-button" disabled={demo}>Change password<ChevronRight size={15}/></button></div></Setting><Setting title="Notifications" description="Choose which updates you want to receive." id="notifications">{[['reminders','Follow-up reminders','A reminder before an upcoming follow-up.'],['updates','Product updates','Occasional news about MedRef.']].map(([key,title,desc])=><div className="setting-line" key={key}><span><strong>{title}</strong><small>{desc}</small></span><button role="switch" aria-checked={toggles[key]} aria-label={title} className={`switch ${toggles[key]?'on':''}`} onClick={()=>setToggles(state=>({...state,[key]:!state[key]}))}><i/></button></div>)}</Setting><Setting title="Appearance" description="Adjust how your workspace looks." id="appearance"><div className="setting-line"><span><strong>Compact rows</strong><small>Show more information in document lists.</small></span><button role="switch" aria-checked={toggles.compact} aria-label="Compact rows" className={`switch ${toggles.compact?'on':''}`} onClick={()=>setToggles(state=>({...state,compact:!state.compact}))}><i/></button></div></Setting><Setting title="Data & privacy" description="Understand how your records are used." id="privacy"><div className="privacy-panel"><ShieldCheck size={20}/><span><strong>Your records stay yours</strong><small>MedRef helps you organize and find information from records you store. Demo content is synthetic and not saved.</small></span></div></Setting></div></section> }
function Setting({title,description,id,children}) { return <section className="setting-section" id={id}><h2>{title}</h2><p>{description}</p><div className="setting-panel">{children}</div></section> }

function AuthPage({mode,setMode,onSubmit,onDemo,error,notice}) { return <main className="auth-page"><header className="auth-top"><a href="#home" className="wordmark"><span className="wordmark-icon"><HeartPulse size={20}/></span><span>medref<span className="wordmark-dot">.</span></span></a><span><ShieldCheck size={15}/>Your records, organized with care</span></header><div className="auth-layout"><section className="auth-story"><small>A CLEARER VIEW OF YOUR HEALTH</small><h1>All your health<br/>information, <em>in one place.</em></h1><p>Keep medical records, visits, and follow-ups together so the details that matter are easier to find.</p><ul><li><Check size={16}/>Organized by patient</li><li><Check size={16}/>Private to your account</li><li><Check size={16}/>Easy to share with your care team</li></ul><blockquote>A more thoughtful way to stay on top of your family's health history.<small>THE MEDREF WORKSPACE</small></blockquote></section><section className="auth-card"><span className="auth-mark"><HeartPulse size={19}/></span><h2>{mode==='login'?'Welcome back':'Create your account'}</h2><p>{mode==='login'?'Sign in to your personal health workspace.':'Start organizing your health records today.'}</p>{notice&&<div className="inline-note">{notice}</div>}{error&&<div className="auth-error" role="alert">{error}</div>}<form onSubmit={onSubmit}>{mode==='register'&&<label>Full name<input name="name" autoComplete="name" placeholder="Your name" required/></label>}<label>Email address<input name="email" type="email" autoComplete="email" placeholder="you@example.com" required/></label><label>Password<input name="password" type="password" autoComplete={mode==='login'?'current-password':'new-password'} placeholder="Enter your password" minLength={mode==='register'?8:undefined} required/></label><button className="primary-button auth-submit">{mode==='login'?'Sign in':'Create account'}<ArrowRight size={17}/></button></form><p className="auth-toggle">{mode==='login'?'New to MedRef?':'Already have an account?'} <button onClick={()=>setMode(mode==='login'?'register':'login')}>{mode==='login'?'Create an account':'Sign in'}</button></p><div className="auth-or"><span>OR</span></div><button className="secondary-button demo-button" onClick={onDemo}><Sparkles size={16}/>Explore with synthetic demo data</button><small className="auth-disclaimer">MedRef helps organize information. It is not a replacement for professional medical advice.</small></section></div><footer className="auth-footer"><span>© 2026 MedRef</span><span>Designed for clarity. Built for your care journey.</span><a href="#help"><CircleHelp size={14}/>Help</a></footer></main> }

function Modal({type,patient,onClose,onSave,onUpload}) { const [file,setFile]=useState(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [progress,setProgress]=useState(0);const [drag,setDrag]=useState(false);const titles={upload:'Upload medical record',patient:'Add patient',medication:'Add medication record',visit:'Record a visit',followup:'Add follow-up',doctor:'Add doctor'};useEffect(()=>{function key(event){if(event.key==='Escape')onClose()}window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[onClose]);async function submit(event){event.preventDefault();setError('');setBusy(true);const values=Object.fromEntries(new FormData(event.currentTarget));try{if(type==='upload')await onUpload(file,values,setProgress);else await onSave(type,values);onClose()}catch(e){setError(e.response?.data?.error||e.message||'Could not save. Try again.')}finally{setBusy(false)}}function field(name,label,props={}){return <label className="form-field" key={name}><span>{label}</span>{props.options?<select name={name} defaultValue={props.options[0]}>{props.options.map(option=><option key={option}>{option}</option>)}</select>:props.textarea?<textarea name={name} rows="3" placeholder={props.placeholder||''}/>:<input name={name} type={props.type||'text'} placeholder={props.placeholder||''} defaultValue={props.value} required={props.required}/>}</label>}return <div className="modal-backdrop" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><section className="modal-window" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><small>MEDREF WORKSPACE</small><h2 id="modal-title">{titles[type]}</h2></div><button className="plain-icon" onClick={onClose} aria-label="Close"><X size={19}/></button></header><form onSubmit={submit}>
    {type==='upload'?<><label className={`drop-area ${drag?'drag':''}`} onDragOver={event=>{event.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)} onDrop={event=>{event.preventDefault();setDrag(false);setFile(event.dataTransfer.files[0])}}><input type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" aria-label="Choose medical document" onChange={event=>setFile(event.target.files[0])}/><span className="drop-icon"><Upload size={21}/></span><strong>{file?file.name:'Drag & drop your medical document here'}</strong><span>{file?`${(file.size/1048576).toFixed(2)} MB`:'or browse from your computer'}</span><small>PDF, JPG, JPEG, PNG · Max 20 MB</small></label>{file&&<div className="chosen-file"><FileText size={18}/><span>{file.name}<small>{(file.size/1048576).toFixed(2)} MB</small></span><button type="button" className="plain-icon" onClick={()=>setFile(null)} aria-label="Remove file"><X size={16}/></button></div>}<div className="form-grid">{field('type','Document type',{options:['Lab report','Blood report','X-ray','Ultrasound','CT','MRI','Prescription','Discharge summary','Other']})}{field('date','Document date',{type:'date',value:new Date().toISOString().slice(0,10)})}</div>{field('doctor','Doctor or clinic',{placeholder:'Optional'})}{field('notes','Notes',{textarea:true,placeholder:'A short note to help you find this later'})}{progress>0&&progress<100&&<div className="progress"><i style={{width:`${progress}%`}}/></div>}</>:type==='patient'?<>{field('name','Patient name',{required:true,placeholder:'Full name'})}<div className="form-grid">{field('dob','Date of birth',{type:'date'})}{field('relationship','Relationship',{options:['Self','Partner','Child','Parent','Family','Other']})}</div></>:type==='medication'?<>{field('name','Medication name',{required:true,placeholder:'Name as recorded by your care team'})}<div className="form-grid">{field('dosage','Dosage',{placeholder:'e.g. 10 mg'})}{field('frequency','Frequency',{placeholder:'e.g. Once daily'})}</div><div className="form-grid">{field('start_date','Start date',{type:'date'})}{field('end_date','End date',{type:'date'})}</div>{field('notes','Notes',{textarea:true,placeholder:'Optional note from your records'})}<p className="form-caution"><ShieldCheck size={15}/>Personal reference only. MedRef does not prescribe medication.</p></>:type==='visit'?<><div className="form-grid">{field('date','Visit date',{type:'date',required:true})}{field('provider','Doctor or clinic',{required:true,placeholder:'Clinician name'})}</div>{field('reason','Reason for visit',{placeholder:'e.g. Routine check-up'})}{field('notes','Notes',{textarea:true,placeholder:'Key details to remember'})}</>:type==='followup'?<><div className="form-grid">{field('date','Follow-up date',{type:'date',required:true})}{field('doctor','Doctor or clinic',{placeholder:'Care team member'})}</div>{field('reason','Reason',{required:true,placeholder:'What should be followed up?'})}<p className="form-caution"><Clock3 size={15}/>A reminder only, not a medical recommendation.</p></>:<>{field('name','Doctor name',{required:true,placeholder:'e.g. Dr. Maya Chen'})}<div className="form-grid">{field('specialty','Specialty',{placeholder:'Primary care'})}{field('clinic','Hospital or clinic',{placeholder:'Clinic name'})}</div><div className="form-grid">{field('phone','Phone',{type:'tel'})}{field('email','Email',{type:'email'})}</div></>}
    {error&&<div className="auth-error" role="alert">{error}</div>}<footer><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" disabled={busy||(type==='upload'&&!file)}>{busy?'Saving...':type==='upload'?'Save record':type==='patient'?'Create profile':type==='visit'?'Save visit':type==='followup'?'Add follow-up':type==='doctor'?'Add doctor':'Save medication'}<Check size={16}/></button></footer></form></section></div> }